mapper.select:
select task_id taskId,workspace_id workspaceId,task_type taskType,required_capability capabilityCode,
       title,task_state state,version,error_code reasonCode,created_at createdAt,updated_at updatedAt,
       correlation_id correlationId
  from aden_task
 where workspace_id=#{workspaceId}
and required_capability=#{capability}

  and (updated_at < #{beforeUpdatedAt} or (updated_at=#{beforeUpdatedAt} and task_id < #{beforeTaskId}))

 order by updated_at desc,task_id desc limit #{limit}

select runner_id runnerId,runner_name displayName,runner_presence presence,
       capabilities_json capabilitiesJson,current_session_epoch currentSessionEpoch,last_seen_at lastSeenAt
  from aden_runner where workspace_id=#{workspaceId} order by created_at,runner_id limit #{limit}

select audit_event_id auditEventId,workspace_id workspaceId,action_code actionCode,outcome,
       actor_type actorType,actor_id actorId,occurred_at occurredAt,correlation_id correlationId
  from aden_audit_event where workspace_id=#{workspaceId}

  and (occurred_at < #{beforeOccurredAt} or (occurred_at=#{beforeOccurredAt} and audit_event_id < #{beforeAuditId}))

 order by occurred_at desc,audit_event_id desc limit #{limit}

select event_id eventId,workspace_id workspaceId,event_seq sequence,aggregate_type aggregateType,
       aggregate_id aggregateId,aggregate_version aggregateVersion,event_type eventType,
       payload_json payloadJson,occurred_at occurredAt,correlation_id correlationId
  from aden_event where workspace_id=#{workspaceId} and event_seq > #{afterSequence}
 order by event_seq asc limit #{limit}
